// ComboBox — Gtk.ComboBox
//
// Generated by bin/11-generate-components, which does not overwrite.
//
// It ships no template, so the markup is the one element its CSS node is, carrying what
  // Adwaita styles combobox with.

import type { ReactNode } from "react"

import { cn } from "@/lib/utils"
import type { WidgetProps } from "@/lib/widget-props"
import type { SensitivityType } from "@/lib/enums"

export interface ComboBoxProps extends WidgetProps {
  className?: string
  children?: ReactNode
  /** gint, from Gtk.ComboBox */
  active?: number

  /** utf8, from Gtk.ComboBox */
  activeId?: string

  /** SensitivityType, from Gtk.ComboBox */
  buttonSensitivity?: SensitivityType

  /** Widget, from Gtk.ComboBox */
  child?: ReactNode

  /** gint, from Gtk.ComboBox */
  entryTextColumn?: number

  /** gboolean, from Gtk.ComboBox */
  hasEntry?: boolean

  /** gboolean, from Gtk.ComboBox */
  hasFrame?: boolean

  /** gint, from Gtk.ComboBox */
  idColumn?: number

  /** TreeModel, from Gtk.ComboBox */
  model?: ReactNode

  /** gboolean, from Gtk.ComboBox */
  popupFixedWidth?: boolean
}

export function ComboBox({ className, children }: ComboBoxProps) {
  return (
    <div className={cn("shadow-none", className)}>
      {children}
    </div>
  )
}
